"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["24374"],{46897(e){e.exports=JSON.parse('{"id":"V4-071","slug":"independent-director","term":"Independent Director","also_known_as":[],"difficulty":"Intermediate","definition":"An independent director is a member of a company\u2019s board who has no material relationship with the company, its management or major shareholders that could affect their ability to make objective judgments.","explanation":["Independent directors provide oversight and challenge to management, helping protect the interests of all shareholders. To be considered independent, a director typically must not be a current or recent employee, have significant business relationships with the company, receive substantial payments beyond director fees, have close family ties to executives or represent a major shareholder. Serving on a board for a very long time may also be seen as affecting independence.","Corporate governance codes and stock exchange rules usually require a significant share of board members to be independent. In the United Kingdom, the governance code recommends that at least half the board, excluding the chair, should be independent non-executive directors. US stock exchanges require a majority of directors to be independent.","For example, an independent director might lead the audit committee, challenging management on accounting judgments without any personal stake in the answers.","Independence on paper does not guarantee independence in practice. Directors chosen by management or with social ties to executives may still be reluctant to challenge them, which is why boards also consider skills, experience and culture."],"note":"","total":1725,"prev":{"slug":"indemnity-principle","term":"Indemnity Principle"},"next":{"slug":"index-fund","term":"Index Fund"}}')}}]);